do $ctrl$
declare
  v_total integer;
begin
  select count(*) into v_total from public.prompts where catalog_version = 'v2.1';
  if v_total < 120 then
    raise exception 'Lot 4 incomplet : % raccourcis importes au lieu de 120.', v_total;
  end if;
end $ctrl$;

drop table lot_prompts;
